version 0.1
model "tutorial-curves"
time calendar monthly from 2026-01 for 36

entity asset solar : Asset.Real

// A curve is a dated series: a forward price, an index, a rate.
// `linear` says how to find a value between two stated points.
curve power_price linear {
  2026-01: 42.10
  2027-01: 44.75
  2028-01: 46.20
}

// Read it with curve_value(name, date). The value tracks the curve period
// by period, so revenue follows the price without the model restating it.
stream solar.energy_revenue on entity asset.solar inflow currency USD {
  schedule every month from 2026-01 to 2028-12
  amount = 1200 * curve_value("power_price", time.date)
}

stream solar.om on entity asset.solar outflow currency USD {
  schedule every month from 2026-01 to 2028-12
  amount = 9000
}

version 0.1
model "tutorial-uncertainty"
time calendar monthly from 2026-01 for 24

entity asset co : Asset.Financial

// A fixed assumption names a number once.
assume monthly_cost = 18000

// A stochastic assumption names a DISTRIBUTION. A deterministic run uses
// its mean; a Monte Carlo run samples it, seeded, so the same run
// reproduces exactly.
assume growth ~ Normal(mean=0.02, stdev=0.008, clip=[0.0, 0.05])

stream co.revenue on entity asset.co inflow currency USD {
  schedule every month from 2026-01 to 2027-12
  amount = 40000 * pow(1 + inputs.growth, time.t / 12.0)
}

stream co.cost on entity asset.co outflow currency USD {
  schedule every month from 2026-01 to 2027-12
  amount = inputs.monthly_cost
}

version 0.1
model "tutorial-options-events"
time calendar monthly from 2026-01 for 24

entity asset senior : Asset.Financial

// An EVENT fires when its condition first becomes true. It can change
// entity state, switch streams off, and exercise an option.
event refinance when time.t >= 12 {
  set entity asset.senior.status = "refinanced"
  deactivate stream loan.debt_service
  exercise option refi_fee
}

// The stream stops two ways: the event deactivates it, and its own
// `active when` reads the state the event set. Either alone is enough.
stream loan.debt_service on entity asset.senior outflow currency USD {
  schedule every month from 2026-01 to 2027-12
  amount = 4200
  active when entity.status != "refinanced"
}

// An OPTION is a payoff that only lands if it is exercised.
option refi_fee type Option.Refinance {
  exercise when false
  payoff 15000
}

